const globalSearchItems=[{title:'الرئيسية',sub:'واجهة الموقع والإحصائيات',target:'home',keys:'الرئيسية home الرئيسية مجتمع community'},{title:'الإدارة العليا',sub:'التسلسل الإداري والقيادة',target:'command',keys:'الإدارة العليا قيادة command admin leadership'},{title:'الفرق',sub:'فرق المجتمع والتخصصات',target:'teams',keys:'الفرق team teams تخصصات'},{title:'الأخبار والإعلانات',sub:'آخر الأخبار والمنشورات',target:'operations',keys:'الأخبار اخبار الإعلانات news announcements'},{title:'القوانين والإجراءات',sub:'فتح صفحة القوانين كاملة',action:'laws',keys:'القوانين قانون إجراءات rules laws policy'},{title:'التقديم للانضمام',sub:'فتح صفحة التقديم',action:'application',keys:'التقديم طلب انضمام تقديم applications recruitment'},{title:'الطلبات والدعم',sub:'الدعم وطلبات الأعضاء',target:'requests',keys:'الدعم طلبات مساعدة support requests'},{title:'سجل الأعضاء',sub:'البحث في أعضاء المجتمع ورتبهم',target:'personnel',keys:'الأعضاء عضو سجل الاعضاء roster personnel members رتبة'},{title:'البث المباشر',sub:'قنوات البث وحالة البث',target:'live',keys:'بث مباشر بثوث stream streams live kick twitch'},{title:'صور الموقع',sub:'مكان الصور المضافة للموقع',target:'home',keys:'صور صورة شعار بروفايل image images logo profile'}];
function runGlobalSearch(q){const box=$('globalSearchResults'),input=$('globalSearch');if(!box||!input)return;const query=q.trim().toLocaleLowerCase();if(!query){box.classList.remove('open');input.setAttribute('aria-expanded','false');box.innerHTML='';return}const results=[];globalSearchItems.forEach(x=>{if((x.title+' '+x.sub+' '+x.keys).toLocaleLowerCase().includes(query))results.push(x)});(data.staff||[]).forEach(x=>{if((x.name+' '+x.role+' '+x.team+' '+x.discord+' '+x.discordId).toLocaleLowerCase().includes(query))results.push({title:x.name||'عضو',sub:'عضو في سجل الأعضاء · '+(x.role||x.team||''),target:'personnel',keys:'staff member'})});(data.news||[]).forEach(x=>{if((x.title+' '+x.body+' '+x.tag).toLocaleLowerCase().includes(query))results.push({title:x.title,sub:'خبر أو إعلان',target:'operations',keys:'news'})});(data.laws||[]).forEach(x=>{if((x.title+' '+x.body+' '+x.type).toLocaleLowerCase().includes(query))results.push({title:x.title,sub:'قانون أو إجراء · فتح صفحة القوانين',action:'laws',keys:'law'})});(data.teams||[]).forEach(x=>{if((x.name+' '+x.desc+' '+x.code).toLocaleLowerCase().includes(query))results.push({title:x.name,sub:'فريق · '+(x.desc||''),target:'teams',keys:'team'})});const unique=results.filter((x,i,a)=>a.findIndex(y=>y.title===x.title&&y.target===x.target&&y.action===x.action)===i).slice(0,9);box.innerHTML=unique.length?unique.map((x,i)=>`<button class="global-search-result" type="button" role="option" data-result="${i}"><span>⌕</span><span>${esc(x.title)}<small>${esc(x.sub)}</small></span></button>`).join(''):'<div class="global-search-empty">لا توجد نتائج مطابقة. جرّب كلمة أخرى.</div>';box.classList.add('open');input.setAttribute('aria-expanded','true');box.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const x=unique[Number(b.dataset.result)];box.classList.remove('open');input.setAttribute('aria-expanded','false');input.value='';if(x.action==='application')openApplicationPage();else if(x.action==='laws')openLawsPage();else{document.body.classList.remove('application-mode','policy-mode');const target=$(x.target||'home');if(target){window.scrollTo({top:target.getBoundingClientRect().top+window.scrollY-90,behavior:'smooth'});$('links').querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+x.target));}}});}
$('globalSearch').addEventListener('input',e=>runGlobalSearch(e.target.value));$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){$('globalSearchResults').classList.remove('open');$('globalSearch').setAttribute('aria-expanded','false')}if(e.key==='Enter'){const first=$('globalSearchResults').querySelector('[data-result]');if(first){e.preventDefault();first.click()}}});document.addEventListener('click',e=>{if(!$('globalSearchWrap')?.contains(e.target)){$('globalSearchResults')?.classList.remove('open');$('globalSearch')?.setAttribute('aria-expanded','false')}});
const originals=new WeakMap();let currentLang=localStorage.getItem('ms3dhTripeLang')||'ar';let currentTheme=localStorage.getItem('ms3dhTripeTheme')||'dark';
function translatePage(){const root=document.documentElement;root.dataset.lang=currentLang;root.lang=currentLang;root.dir=currentLang==='en'?'ltr':'rtl';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!originals.has(node))originals.set(node,node.nodeValue);const original=originals.get(node);const clean=original.trim();if(!clean)continue;const translated=i18n[clean];if(currentLang==='en'&&translated){node.nodeValue=original.replace(clean,translated)}else if(currentLang==='ar'){node.nodeValue=original}}
const attrMap={'placeholder':{'ابحث بالاسم أو Discord أو الرتبة...':'Search by name, Discord, or role...'},'aria-label':{'بحث الأعضاء':'Search members','Switch language':'تغيير اللغة','Switch theme':'تغيير المظهر'}};document.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{for(const attr of ['placeholder','aria-label']){if(!el.hasAttribute(attr))continue;const key=attr+'|'+el.id;if(!el.dataset['orig'+attr])el.dataset['orig'+attr]=el.getAttribute(attr);const orig=el.dataset['orig'+attr];if(currentLang==='en'&&attrMap[attr]?.[orig])el.setAttribute(attr,attrMap[attr][orig]);else if(currentLang==='ar')el.setAttribute(attr,orig)}});const langBtn=$('langToggle');if(langBtn){const label=currentLang==='ar'?'EN':'العربية';langBtn.innerHTML='<svg class="mono-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/></svg><span>'+label+'</span>';}const themeBtn=$('themeToggle');if(themeBtn){const isDark=currentTheme==='dark';const label=isDark?(currentLang==='en'?'Light':'نهاري'):(currentLang==='en'?'Dark':'ليلي');const icon=isDark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>':'<path d="M20.5 15.5A8.5 8.5 0 0 1 8.5 3.5 8.5 8.5 0 1 0 20.5 15.5Z"/>';themeBtn.innerHTML='<svg class="mono-icon" viewBox="0 0 24 24" aria-hidden="true">'+icon+'</svg><span>'+label+'</span>';}tick();}
function applyTheme(){document.documentElement.dataset.theme=currentTheme;const b=$('themeToggle');if(b){const isDark=currentTheme==='dark';const label=isDark?(currentLang==='en'?'Light':'نهاري'):(currentLang==='en'?'Dark':'ليلي');const icon=isDark?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>':'<path d="M20.5 15.5A8.5 8.5 0 0 1 8.5 3.5 8.5 8.5 0 1 0 20.5 15.5Z"/>';b.innerHTML='<svg class="mono-icon" viewBox="0 0 24 24" aria-hidden="true">'+icon+'</svg><span>'+label+'</span>';}}
$('langToggle').onclick=()=>{currentLang=currentLang==='ar'?'en':'ar';localStorage.setItem('ms3dhTripeLang',currentLang);translatePage();applyTheme();if(document.body.classList.contains('application-mode'))renderApplicationPage()};$('themeToggle').onclick=()=>{currentTheme=currentTheme==='dark'?'light':'dark';localStorage.setItem('ms3dhTripeTheme',currentTheme);applyTheme()};
const langObserver=new MutationObserver(records=>{if(currentLang!=='en')return;for(const rec of records){for(const node of rec.addedNodes){if(node.nodeType===Node.TEXT_NODE){const val=node.nodeValue.trim();if(i18n[val])node.nodeValue=node.nodeValue.replace(val,i18n[val])}else if(node.nodeType===Node.ELEMENT_NODE){const walker=document.createTreeWalker(node,NodeFilter.SHOW_TEXT);let child;while(child=walker.nextNode()){if(!originals.has(child))originals.set(child,child.nodeValue);const original=originals.get(child),clean=original.trim();if(i18n[clean])child.nodeValue=original.replace(clean,i18n[clean])}}}}});langObserver.observe(document.body,{childList:true,subtree:true});applyTheme();translatePage();loadSharedContent().finally(()=>{applyTheme();translatePage();render();syncDiscord(false,true);});
