// Add restrained animated signal bars between the major content sections.
(()=>{const ids=['command','commandchain','teams','operations','laws','personnel','live','signin'];const labels=['COMMUNITY STATUS','COMMAND STRUCTURE','TEAM DEPLOYMENT','COMMUNITY BULLETIN','POLICY SIGNAL','MEMBER DATABASE','LIVE CHANNELS','RECRUITMENT DESK'];ids.forEach((id,i)=>{const section=document.getElementById(id);if(!section||section.nextElementSibling?.classList.contains('section-signal'))return;const bar=document.createElement('div');bar.className='section-signal';bar.setAttribute('aria-hidden','true');bar.innerHTML='<span class="signal-track"></span><span class="signal-core"><span></span></span><span class="signal-label">'+labels[i]+'</span>';section.insertAdjacentElement('afterend',bar)})})();

// Scroll progress and lightweight interaction feedback
(()=>{
 const bar=document.getElementById('scrollProgressBar');
 let queued=false;
 const updateProgress=()=>{queued=false;if(!bar)return;const doc=document.documentElement;const max=doc.scrollHeight-window.innerHeight;const progress=max>0?Math.min(1,Math.max(0,window.scrollY/max)):0;bar.style.transform=`scaleX(${progress})`;};
 window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateProgress)}},{passive:true});
 window.addEventListener('resize',updateProgress,{passive:true});updateProgress();
 document.addEventListener('click',e=>{const target=e.target.closest('.btn,.filter,.menu,.global-search-result');if(!target||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=target.getBoundingClientRect();const dot=document.createElement('span');dot.className='ripple-dot';const size=Math.max(rect.width,rect.height)*1.25;dot.style.width=dot.style.height=size+'px';dot.style.left=(e.clientX-rect.left-size/2)+'px';dot.style.top=(e.clientY-rect.top-size/2)+'px';target.appendChild(dot);dot.addEventListener('animationend',()=>dot.remove(),{once:true});});
})();

